SELECT count(*)
FROM public.nocode_record_process
WHERE object_id = #{object}
AND record_id = #{record}
AND status = 'RUNNING'
AND deleted = 0

SELECT *
FROM public.nocode_record_process
WHERE application_id = #{app}
AND object_id = #{object}
AND record_id = #{record}
AND deleted = 0
ORDER BY id DESC
